-- ---------------------------------------------------------------
-- art:visuais:1 · Ponto, linha, forma e cor
-- ---------------------------------------------------------------
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:1', 0, 'mc', $q$As cores primárias na pintura, que não nascem da mistura de outras cores, são:$q$, $j${"opts":["Vermelho, amarelo e azul","Verde, roxo e laranja","Preto, branco e cinza","Rosa, marrom e dourado"],"a":0}$j$, $q$Na pintura, vermelho, amarelo e azul são primárias; misturando-as surgem as secundárias.$q$, 1);
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:1', 1, 'mc', $q$Misturando azul e amarelo obtemos a cor secundária:$q$, $j${"opts":["Verde","Roxo","Laranja","Marrom"],"a":0}$j$, $q$Azul + amarelo = verde; vermelho + azul = roxo; vermelho + amarelo = laranja.$q$, 1);
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:1', 2, 'mc', $q$Cores como vermelho, laranja e amarelo, associadas ao fogo e ao sol, são chamadas de:$q$, $j${"opts":["Cores quentes","Cores frias","Cores neutras","Cores primárias"],"a":0}$j$, $q$Cores quentes transmitem energia e calor; as frias (azul, verde, violeta) transmitem calma.$q$, 1);
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:1', 3, 'tf', $q$Julgue a afirmação sobre a linha$q$, $j${"stmt":"A linha é um elemento visual: pode ser reta, curva, grossa ou fina, e transmite sensações diferentes, como calma, movimento ou tensão.","a":true}$j$, $q$Verdadeiro: linhas horizontais sugerem calma; diagonais, movimento; quebradas, tensão.$q$, 1);
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:1', 4, 'bank', $q$Complete a frase sobre os elementos visuais$q$, $j${"parts":["O "," é o menor elemento da linguagem visual; o contorno que delimita um objeto define a sua ","."],"a":["ponto","forma"],"extra":["som","rima"]}$j$, $q$Do ponto nasce a linha; da linha, a forma — a base de qualquer imagem.$q$, 1);
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:1', 5, 'match', $q$Associe o grupo de cores aos exemplos$q$, $j${"pairs":[["Cores quentes","Vermelho, laranja e amarelo"],["Cores frias","Azul, verde e violeta"],["Cores neutras","Preto, branco e cinza"],["Cores complementares","Opostas no círculo cromático, como vermelho e verde"]]}$j$, $q$O círculo cromático organiza as cores e ajuda a combiná-las.$q$, 2);

-- art:visuais:2 · Composição e técnicas
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:2', 0, 'mc', $q$A técnica de pintura feita sobre a parede com o reboco ainda úmido, usada por Michelangelo na Capela Sistina, é o:$q$, $j${"opts":["Afresco","Grafite","Mosaico","Origami"],"a":0}$j$, $q$No afresco, o pigmento é aplicado no reboco úmido e se incorpora à parede ao secar.$q$, 2);
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:2', 1, 'mc', $q$A arte de compor imagens com pequenos pedaços de pedra, vidro ou cerâmica é o:$q$, $j${"opts":["Mosaico","Aquarela","Afresco","Croqui"],"a":0}$j$, $q$O mosaico monta a imagem peça por peça; foi muito usado na arte romana e bizantina.$q$, 1);
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:2', 2, 'mc', $q$Na xilogravura, muito usada nos folhetos de cordel nordestinos, a imagem é:$q$, $j${"opts":["Entalhada numa matriz de madeira e depois impressa no papel","Pintada a óleo sobre tela","Esculpida em mármore","Fotografada"],"a":0}$j$, $q$Xilo = madeira: entalha-se a matriz, aplica-se tinta e imprime-se no papel.$q$, 2);
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:2', 3, 'tf', $q$Julgue a afirmação sobre a escultura$q$, $j${"stmt":"Escultura é uma linguagem tridimensional: tem altura, largura e profundidade, e pode ser feita em argila, pedra, madeira ou metal.","a":true}$j$, $q$Verdadeiro: diferentemente da pintura, a escultura ocupa o espaço em três dimensões.$q$, 1);
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:2', 4, 'bank', $q$Complete a frase sobre as técnicas de pintura$q$, $j${"parts":["Na pintura em "," as cores são diluídas em água e ficam transparentes; a pintura a "," seca devagar e permite cores intensas, como nas telas renascentistas."],"a":["aquarela","óleo"],"extra":["mosaico","lápis"]}$j$, $q$Aquarela: leveza e transparência. Óleo: intensidade e retoques demorados.$q$, 2);
select public.fj_seed_q('art', 'art:visuais', 'art:visuais:2', 5, 'match', $q$Associe a linguagem à sua característica$q$, $j${"pairs":[["Pintura","Bidimensional, feita com tintas"],["Escultura","Tridimensional"],["Gravura","Imagem impressa a partir de uma matriz"],["Colagem","Composição com papéis e materiais colados"]]}$j$, $q$Cada linguagem visual tem seu suporte e seu modo de fazer.$q$, 1);

