select public.fj_seed_q('art', 'art:historia', 'art:historia:1', 1, 'mc', $q$No Egito antigo, a arte seguia a lei da frontalidade, em que:$q$, $j${"opts":["O tronco aparece de frente e o rosto e as pernas de perfil","Tudo era pintado de costas","Só se pintavam animais","As figuras eram sempre redondas"],"a":0}$j$, $q$A lei da frontalidade dava rigidez e caráter sagrado às figuras egípcias.$q$, 2);
select public.fj_seed_q('art', 'art:historia', 'art:historia:1', 2, 'mc', $q$Os gregos antigos buscavam na escultura:$q$, $j${"opts":["A proporção e a beleza ideal do corpo humano","O exagero e o grotesco","Apenas figuras de animais","A abstração total"],"a":0}$j$, $q$Equilíbrio, proporção e idealização do corpo: o legado grego que o Renascimento retomou.$q$, 2);
select public.fj_seed_q('art', 'art:historia', 'art:historia:1', 3, 'tf', $q$Julgue a afirmação sobre a arte romana$q$, $j${"stmt":"O Coliseu e os aquedutos mostram que os romanos se destacaram na arquitetura e na engenharia.","a":true}$j$, $q$Verdadeiro: arcos, abóbadas e concreto romano sustentaram obras monumentais.$q$, 1);
select public.fj_seed_q('art', 'art:historia', 'art:historia:1', 4, 'bank', $q$Complete a frase sobre a arte medieval$q$, $j${"parts":["Na Idade Média, os vitrais coloridos decoravam as catedrais ","; os mosaicos dourados brilhavam na arte ","."],"a":["góticas","bizantina"],"extra":["egípcias","rupestre"]}$j$, $q$O gótico buscava luz e altura; a arte bizantina cobria igrejas de mosaicos dourados.$q$, 3);
select public.fj_seed_q('art', 'art:historia', 'art:historia:1', 5, 'match', $q$Associe o período à sua marca$q$, $j${"pairs":[["Arte rupestre","Pinturas em cavernas"],["Egito","Pirâmides e lei da frontalidade"],["Grécia","Esculturas de proporção ideal"],["Idade Média","Catedrais góticas e vitrais"]]}$j$, $q$Um passeio da caverna à catedral: cada época com sua forma de ver o mundo.$q$, 2);

